<?php
/**
 * Plugin Name: NESPORTS3 Updater V60 (Elementor Live Edit Sync & Cache Buster)
 * Description: Enables instant Elementor live typing previews, fixes Publish button dirty state, provides dynamic script cache-busting, and synchronizes Elementor saves with the Master Dashboard.
 * Version: 60.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v60_sync() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (stripos($f, 'nesport') !== false) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }

    $payloads = array(
        'assets/js/nesports-frontend.js' => base64_decode(''),
        'includes/helpers.php' => base64_decode(''),
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/class-nesports-elementor.php' => base64_decode(''),
        'includes/elementor-widgets/widget-story.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
        'assets/css/nesports-admin.css' => base64_decode(''),

    );

    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }

    // 1. Deactivate old updater/patch plugins in database option
    $active = get_option('active_plugins', array());
    if (is_array($active)) {
        $clean_active = array();
        foreach ($active as $p) {
            if (stripos($p, 'updater-v') !== false || stripos($p, 'nesports-patch') !== false) {
                continue;
            }
            $clean_active[] = $p;
        }
        update_option('active_plugins', $clean_active);
    }

    // 2. Clear Elementor Cache
    if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
    }

    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v60']) && $_GET['nesports_apply_v60'] === '1') {
        $res = run_nesports_v60_sync();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
    run_nesports_v60_sync();
}, 1);

register_activation_hook(__FILE__, 'run_nesports_v60_sync');
